#!/usr/bin/env node
// Regenerates the vendored `codex app-server` TypeScript bindings.
//
// The Codex version is read from the codex-cli pin in
// .github/workflows/scheduled-real-cli-e2e.yml, so bumping that pin and
// re-running this script is the whole upgrade. The bindings are generated by
// the CLI itself (`codex app-server generate-ts`, stable surface only — no
// `--experimental`), which needs no login and makes no model request.
//
//   node scripts/generate-codex-app-server-types.mjs           # regenerate
//   node scripts/generate-codex-app-server-types.mjs --check   # fail on drift
//   node scripts/generate-codex-app-server-types.mjs --version 0.159.3
//
// --check regenerates into a temp dir and exits non-zero when the result
// differs from what is committed, for a CI schema-drift job.

import { spawnSync } from 'node:child_process';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const workflowPath = path.join(repoRoot, '.github', 'workflows', 'scheduled-real-cli-e2e.yml');
const targetDir = path.join(repoRoot, 'src', 'main', 'orchestrators', 'adapters', 'codex-protocol', 'generated');
const metaFile = path.join(repoRoot, 'src', 'main', 'orchestrators', 'adapters', 'codex-protocol', 'generated-meta.ts');

const args = process.argv.slice(2);
const check = args.includes('--check');
const versionFlag = args.indexOf('--version');
const version = versionFlag >= 0 ? args[versionFlag + 1] : readPinnedVersion();

function readPinnedVersion() {
  const yaml = fs.readFileSync(workflowPath, 'utf8');
  const match = /codex-cli\)[\s\S]*?version=([0-9][^"\s]*)/.exec(yaml);
  if (!match) throw new Error(`Could not find the codex-cli version pin in ${workflowPath}`);
  return match[1];
}

function run(cmd, cmdArgs, opts = {}) {
  const result = spawnSync(cmd, cmdArgs, { stdio: 'inherit', shell: process.platform === 'win32', ...opts });
  if (result.error) throw result.error;
  if (result.status !== 0) throw new Error(`${cmd} ${cmdArgs.join(' ')} exited with ${result.status}`);
}

/** File contents with CRLF normalized, so a Windows checkout doesn't read as drift. */
function readLf(file) {
  return fs.readFileSync(file, 'utf8').replace(/\r\n/g, '\n');
}

function listFiles(dir, base = dir) {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const full = path.join(dir, entry.name);
    return entry.isDirectory() ? listFiles(full, base) : [path.relative(base, full).split(path.sep).join('/')];
  });
}

function methodsOf(outDir, file) {
  const source = fs.readFileSync(path.join(outDir, file), 'utf8');
  const methods = [...source.matchAll(/"method": "([^"]+)"/g)].map((m) => m[1]);
  if (methods.length === 0) throw new Error(`No methods found in ${file}`);
  return methods;
}

function metaModule(v, outDir) {
  const list = (methods) => methods.map((m) => `  '${m}',`).join('\n');
  return [
    '// Written by scripts/generate-codex-app-server-types.mjs. Do not edit by hand.',
    '',
    '/** Codex CLI version the vendored app-server bindings in ./generated came from. */',
    `export const CODEX_APP_SERVER_SCHEMA_VERSION = '${v}';`,
    '',
    '/** Command that produced ./generated (stable surface; no --experimental). */',
    `export const CODEX_APP_SERVER_GENERATE_COMMAND = 'npx -y @openai/codex@${v} app-server generate-ts --out <dir>';`,
    '',
    '/** Runtime list of `ServerNotification` methods (the generated bindings are type-only). */',
    'export const CODEX_SERVER_NOTIFICATION_METHODS = [',
    list(methodsOf(outDir, 'ServerNotification.ts')),
    '] as const;',
    '',
    '/** Runtime list of `ServerRequest` methods. */',
    'export const CODEX_SERVER_REQUEST_METHODS = [',
    list(methodsOf(outDir, 'ServerRequest.ts')),
    '] as const;',
    '',
  ].join('\n');
}

const workDir = fs.mkdtempSync(path.join(os.tmpdir(), 'codex-generate-ts-'));
try {
  const outDir = path.join(workDir, 'out');
  console.log(`Generating codex app-server bindings from @openai/codex@${version}`);
  run('npx', ['-y', `@openai/codex@${version}`, 'app-server', 'generate-ts', '--out', outDir], { cwd: workDir });

  if (check) {
    const generated = listFiles(outDir).sort();
    const committed = listFiles(targetDir).sort();
    const drift = [];
    const committedSet = new Set(committed);
    for (const file of generated) {
      if (!committedSet.has(file)) drift.push(`added: ${file}`);
      else if (readLf(path.join(outDir, file)) !== readLf(path.join(targetDir, file))) {
        drift.push(`changed: ${file}`);
      }
    }
    const generatedSet = new Set(generated);
    for (const file of committed) if (!generatedSet.has(file)) drift.push(`removed: ${file}`);
    const versionDrift = !fs.existsSync(metaFile) || readLf(metaFile) !== metaModule(version, outDir);
    if (drift.length || versionDrift) {
      console.error(`Vendored codex app-server bindings are out of date with @openai/codex@${version}:`);
      for (const line of drift.slice(0, 50)) console.error(`  ${line}`);
      if (drift.length > 50) console.error(`  …and ${drift.length - 50} more`);
      if (versionDrift) console.error('  changed: generated-meta.ts');
      console.error('Run: node scripts/generate-codex-app-server-types.mjs');
      // exitCode rather than exit() so the finally block still removes the temp dir.
      process.exitCode = 1;
    } else {
      console.log('Vendored codex app-server bindings match.');
    }
  } else {
    fs.rmSync(targetDir, { recursive: true, force: true });
    fs.cpSync(outDir, targetDir, { recursive: true });
    fs.writeFileSync(metaFile, metaModule(version, outDir));
    console.log(`Wrote ${listFiles(targetDir).length} files to ${path.relative(repoRoot, targetDir)}`);
  }
} finally {
  fs.rmSync(workDir, { recursive: true, force: true });
}
